		setQuillHtml(incomingHtml) {
			const safeHtml = purify.sanitize(incomingHtml ?? "", { USE_PROFILES: { html: true } });
			const delta = this.quill?.clipboard.convert({ html: safeHtml });
			this.quill?.setContents(delta ?? [], "silent");
		}
