	//#region src/06-components/toast/index.ts
	var Toast = class {
		elToastContainer = null;
		list = [];
		constructor() {}
		createToastNotification(message) {
			message.id = +/* @__PURE__ */ new Date();
			if (message.type === "Entities.Alert.Info") message.type = "alert-info";
			this.list.push(message);
			this.addToastMessage(message);
		}
		clearToastNotifications() {
			this.list = [];
			this.elToastContainer?.remove();
		}
		addToastMessage(message) {
			if (!this.elToastContainer) {
				this.elToastContainer = document.createElement("div");
				this.elToastContainer.className = "toast";
				document.getElementById("transitionContainer")?.prepend(this.elToastContainer);
			}
			let fragment = tmplToastMessage.content.cloneNode(true);
			let toastMessage = fragment.querySelector(".toast-notification");
			let toastMessageTitle = fragment.querySelector(".toast-notification-content-text-title");
			let toastMessageBody = fragment.querySelector(".toast-notification-content-text-body");
			let toastMessageClose = fragment.querySelector(".toast-notification-content-close");
			toastMessage.setAttribute("data-id", String(message.id));
			toastMessage.setAttribute("data-type", message.type);
			toastMessage.style.setProperty("--time-to-live", `${message.timeToLive}s`);
			toastMessageTitle.innerText = message.title || "";
			toastMessageBody.innerHTML = message.body;
			if (message.hasClose) {
				toastMessage.classList.add("has-close");
				toastMessageClose.innerHTML = Helpers.placeIcon("x");
			}
			let toastMessageIcon = toastMessage.querySelector(".toast-notification-content-icon");
			switch (message.type) {
				case "alert-error":
					toastMessageIcon.innerHTML = Helpers.placeIcon("warning-octagon", "m");
					break;
				case "alert-info":
					toastMessageIcon.innerHTML = Helpers.placeIcon("info", "m");
					break;
				case "alert-success":
					toastMessageIcon.innerHTML = Helpers.placeIcon("check-circle-bold", "m");
					break;
				case "alert-warning":
					toastMessageIcon.innerHTML = Helpers.placeIcon("warning", "m");
					break;
				default:
					toastMessageIcon.innerHTML = Helpers.placeIcon("info", "m");
					break;
			}
			this.elToastContainer.prepend(toastMessage);
			toastMessage.addEventListener("click", () => {
				this.removeToastMessage(message.id);
			});
			toastMessage.addEventListener("animationend", (animation) => {
				switch (animation.animationName) {
					case "toast-destruction":
						const toastId = Number(toastMessage.dataset.id);
						toastMessage.remove();
						const position = this.list.findIndex((message) => message.id === toastId);
						if (position > -1) this.list.splice(position, 1);
						if (this.list.length === 0) {
							this.elToastContainer?.remove();
							this.elToastContainer = null;
						}
						break;
					case "toast-progress":
						if (message.timeToLive > 0) toastMessage?.classList.add("is-removing");
						break;
				}
			});
		}
		removeToastMessage(id) {
			document.querySelector(`.toast-notification[data-id="${id}"]`)?.classList.add("is-removing");
		}
	};
